module DE = Downwards_env
module T = Flambda2_types
module U = One_continuation_use
open Apply_cont_rewrite_id
open Port_monad

type t =
  { continuation : Continuation.t;
    arity : [`Unarized] Flambda_arity.t;
    uses : One_continuation_use.t list
  }

(** val continuation : t -> Continuation.t **)

let continuation t0 = t0.continuation

(** val arity : t -> [ `Unarized ] Flambda_arity.t **)

let arity t0 = t0.arity

(** val uses : t -> One_continuation_use.t list **)

let uses t0 = t0.uses

(** val create : Continuation.t -> [ `Unarized ] Flambda_arity.t -> t coq_M **)

let create continuation0 arity0 =
  { continuation = continuation0; arity = arity0; uses = [] }

(** val print : Format.formatter -> t -> unit coq_M **)

let print ppf t0 =
  let { continuation = continuation0; arity = arity0; uses = uses0 } = t0 in
  Format.fprintf ppf
    "@[<hov 1>(@[<hov 1>(continuation@ %a)@]@ @[<hov 1>(arity@ %a)@]@ @[<hov \
     1>(uses@ %a)@])@]"
    Continuation.print continuation0 Flambda_arity.print arity0
    ((fun x__1 x__2 x__3 x__4 ->
       Format.pp_print_list ?pp_sep:x__1 x__2 x__3 x__4)
       (Some Format.pp_print_space) One_continuation_use.print)
    uses0

(** val add_use : t -> One_continuation_use.t -> t coq_M **)

let add_use t0 use =
  Port_monad.try_with
    (fun _ ->
      let arity0 =
        Flambda2_types.arity_of_list (One_continuation_use.arg_types use)
      in
      let () =
        if not (Flambda_arity.equal_ignoring_subkinds arity0 t0.arity)
        then
          Misc.fatal_errorf
            "Arity of use (%a) doesn't match continuation's arity (%a)"
            Flambda_arity.print arity0 Flambda_arity.print t0.arity
        else ()
      in
      { continuation = t0.continuation;
        arity = t0.arity;
        uses = use :: t0.uses
      })
    Port_monad.fatal_error_exception
    (fun _ ->
      let bt = Printexc.get_raw_backtrace () in
      let () =
        Format.eprintf
          "\n\
           %tContext is:%t adding use of %a with arg types@ (%a);@ existing \
           uses:@ %a; environment:@ %a"
          Flambda_colours.error Flambda_colours.pop Continuation.print
          t0.continuation
          ((fun x__1 x__2 x__3 x__4 ->
             Format.pp_print_list ?pp_sep:x__1 x__2 x__3 x__4)
             (Some Format.pp_print_space) Flambda2_types.print)
          (One_continuation_use.arg_types use)
          print t0 Downwards_env.print
          (One_continuation_use.env_at_use use)
      in
      Printexc.raise_with_backtrace
        (Port_monad.exn_make Port_monad.fatal_error_exception ())
        bt)

(** val union : t -> t -> t coq_M **)

let union t1 t2 =
  let () =
    if not (Continuation.equal t1.continuation t2.continuation)
    then
      Misc.fatal_errorf
        "Cannot union continuation uses for different continuations %a and \
         %a.@ Continuation uses t1:@ %a@ and@ t2:@ %a"
        Continuation.print t1.continuation Continuation.print t2.continuation
        print t1 print t2
    else ()
  in
  let () =
    if
      Flambda_features.kind_checks ()
      && not (Flambda_arity.equal_ignoring_subkinds t1.arity t2.arity)
    then
      Misc.fatal_errorf
        "Arity of continuation uses (%a) doesn't match arity of continuation \
         uses (%a).  Continuation uses t1:@ %a@ and@ t2:@ %a"
        Flambda_arity.print t1.arity Flambda_arity.print t2.arity print t1 print
        t2
    else ()
  in
  { continuation = t1.continuation; arity = t1.arity; uses = t1.uses @ t2.uses }

(** val number_of_uses : t -> int coq_M **)

let number_of_uses t0 = List.length t0.uses

(** val get_uses : t -> One_continuation_use.t list coq_M **)

let get_uses t0 = t0.uses

type arg_at_use =
  { arg_type : Flambda2_types.t;
    typing_env : Flambda2_types.Typing_env.t
  }

(** val arg_type : arg_at_use -> Flambda2_types.t **)

let arg_type a = a.arg_type

(** val typing_env : arg_at_use -> Flambda2_types.Typing_env.t **)

let typing_env a = a.typing_env

type arg_types_by_use_id = arg_at_use Map.t list

(** val print_arg_type_at_use : Format.formatter -> arg_at_use -> unit coq_M **)

let print_arg_type_at_use ppf a =
  let { arg_type = arg_type0; typing_env = _ } = a in
  Flambda2_types.print ppf arg_type0

(** val add_value_to_arg_map : arg_at_use Map.t -> Flambda2_types.t ->
    One_continuation_use.t -> arg_at_use Map.t coq_M **)

let add_value_to_arg_map arg_map arg_type0 use =
  let env_at_use = One_continuation_use.env_at_use use in
  let typing_env0 = Downwards_env.typing_env env_at_use in
  let arg_at_use0 = { arg_type = arg_type0; typing_env = typing_env0 } in
  Apply_cont_rewrite_id.Map.add
    (One_continuation_use.id use)
    arg_at_use0 arg_map

(** val add_uses_to_arg_maps : arg_types_by_use_id -> One_continuation_use.t
    list -> arg_types_by_use_id coq_M **)

let add_uses_to_arg_maps arg_maps uses0 =
  List.fold_left
    (fun arg_maps0 use ->
      let arg_types = One_continuation_use.arg_types use in
      fst
        (Misc.Stdlib.List.map2_prefix
           (fun arg_map arg_type0 -> add_value_to_arg_map arg_map arg_type0 use)
           arg_maps0 arg_types))
    arg_maps uses0

(** val empty_arg_maps : [ `Unarized ] Flambda_arity.t -> arg_types_by_use_id
    coq_M **)

let empty_arg_maps arity0 =
  List.map
    (fun _ -> Apply_cont_rewrite_id.Map.empty)
    (Flambda_arity.unarized_components arity0)

(** val get_arg_types_by_use_id : t -> arg_types_by_use_id coq_M **)

let get_arg_types_by_use_id t0 =
  add_uses_to_arg_maps (empty_arg_maps t0.arity) t0.uses

(** val get_arg_types_by_use_id_for_invariant_params : [ `Unarized ]
    Flambda_arity.t -> t list -> arg_types_by_use_id coq_M **)

let get_arg_types_by_use_id_for_invariant_params arity0 l =
  List.fold_left
    (fun arg_maps t0 ->
      let () =
        if
          not
            (Misc.Stdlib.List.is_prefix Flambda_kind.equal
               (List.map Flambda_kind.With_subkind.kind
                  (Flambda_arity.unarized_components arity0))
               (List.map Flambda_kind.With_subkind.kind
                  (Flambda_arity.unarized_components t0.arity)))
        then
          Misc.fatal_errorf
            "Arity of invariant params@ (%a) is not a prefix of the arity of \
             the continuation uses@ (%a)"
            Flambda_arity.print arity0 Flambda_arity.print t0.arity
        else ()
      in
      add_uses_to_arg_maps arg_maps t0.uses)
    (empty_arg_maps arity0) l

(** val get_use_ids : t -> Apply_cont_rewrite_id.Set.t coq_M **)

let get_use_ids t0 =
  List.fold_left
    (fun uses0 use ->
      Apply_cont_rewrite_id.Set.add (One_continuation_use.id use) uses0)
    Apply_cont_rewrite_id.Set.empty t0.uses

(** val get_typing_env_no_more_than_one_use : t -> Flambda2_types.Typing_env.t
    option coq_M **)

let get_typing_env_no_more_than_one_use t0 =
  match t0.uses with
  | [] -> None
  | use :: l -> (
    match l with
    | [] ->
      Some (Downwards_env.typing_env (One_continuation_use.env_at_use use))
    | _ :: _ ->
      Misc.fatal_errorf "Only zero or one continuation use(s) expected:@ %a"
        print t0)

(** val mark_non_inlinable : t -> t coq_M **)

let mark_non_inlinable t0 =
  { continuation = t0.continuation;
    arity = t0.arity;
    uses = List.map One_continuation_use.mark_non_inlinable t0.uses
  }

(** val clear_uses : t -> t coq_M **)

let clear_uses t0 =
  { continuation = t0.continuation; arity = t0.arity; uses = [] }
